import { use } from 'react';
import { Row } from '@/modules/page-blocks/components/NodeRenderer';
import { PageTitleBar } from '@/modules/shared/PageTitleBar';
import type { PageDocument } from '@/modules/page-blocks/types/blocks';
import { PageSeo } from '@/modules/shared/PageSeo';
import { PAGES } from '@/core/config/pages';
import { useRouteKey } from '@/core/hooks/useRouteKey';
import { useLocale } from '@/i18n/LocaleContext';

/** Lazily-loaded page documents generated by `scripts/convert-pages.ts`. */
const DOCUMENTS = import.meta.glob<PageDocument>('/src/content/pages/*.json', { import: 'default' });
const cache = new Map<string, Promise<PageDocument | null>>();

function loadDocument(file: string): Promise<PageDocument | null> {
  let promise = cache.get(file);
  if (!promise) {
    const loader = DOCUMENTS[file];
    promise = loader ? loader() : Promise.resolve(null);
    cache.set(file, promise);
  }
  return promise;
}

/**
 * Generic route component for content pages recreated from the original's WPBakery
 * layouts (service pages, about, industries, careers…).
 */
export default function BlockPage() {
  const key = useRouteKey();
  const { locale } = useLocale();
  if (!key) throw new Error('BlockPage rendered outside a registered route');
  const effective = PAGES[key].locales.includes(locale) ? locale : 'en';
  const doc = use(loadDocument(`/src/content/pages/${key}.${effective}.json`));
  if (!doc) throw new Response('Page content missing', { status: 404 });

  return (
    <>
      <PageSeo routeKey={key} />
      {doc.titleBar && <PageTitleBar data={doc.titleBar} />}
      {doc.rows.map((row, i) => (
        <Row key={row.id ?? i} row={row} />
      ))}
    </>
  );
}
